    @check_rat
    def test_ipconnectivity(self, **kwargs):
        """
        Test IP connectivity to given address

        :param kwargs (str) destination_ip: IP whose connectivity is to be tested
        :param kwargs (int) payload_size: size of payload in int
        :param kwargs (int) dscp: values of IPv4 and IPv6 headers to classify data packets and manage network traffic
        :param kwargs (str) source_interface_name: Name of the external interface selected as source
        :param kwargs (str) source_ip: (optional) IPv4/IPv6 address of the external interface selected as source
        :param kwargs (str) connection: (optional) Unique identifier for a certain connections.

        returns: It returns IP connectivity test result dict

        """
        retry = 10
        destination_ip = kwargs["destination_ip"]
        payload_size = kwargs["payload_size"]
        dscp = kwargs["dscp"]
        source_interface_name = kwargs.get("source_interface_name", "default")
        source_ip = kwargs.get("source_ip")
        alias = kwargs.get("alias", "default")
        result_dict = {}
        operation_id = ''
        for i in range(retry):
            try:
                operation_id = self.factory.cu_oam.start_ip_connectivity_test(destination_ip=destination_ip, payload_size=payload_size, dscp=dscp, source_interface_name=source_interface_name, source_ip=source_ip, connection=alias)

            except Exception as e:
                logger.error("Ping failed: {}".format(e))

            for _ in range(10):
                result_dict = self.factory.cu_oam.get_ip_connectivity_test_result(operation_id=operation_id,connection=alias)
                output = self._verify_status(result_dict, "Successful")
                if not output:
                    time.sleep(2)
                    continue
                else:
                    return result_dict["result"]
        else:
            logger.error(
                """IP connectivity unsuccessful after {} retries.\nResponse status is : {}.\nResult dict is:{}""".format(
                    retry, result_dict["status"], result_dict))

    def collect_snapshot(self, **kwargs):
        """
        Gets local snapshot and saves it under given directory.
        :param kwargs (float) request_timeout: timeout in seconds for sending request to OAM
        :param kwargs (int) operation_timeout: timeout in seconds for getting snapshot
        :param kwargs (str) connection: (optional) Unique identifier for a certain connections.

        """

        request_timeout = kwargs.get("request_timeout", None)
        operation_timeout = kwargs.get("operation_timeout", 600)
        alias = kwargs.get("alias", "default")
        target_path = os.path.join(os.getcwd(),'execution_logs')
        logger.debug("target path :: {}".format(target_path))
        if not os.path.exists(target_path):
            os.makedirs(target_path)
        logger.debug("Collecting snap shot..")
        self.factory.cu_oam.get_local_snapshot(
            directory=target_path, request_timeout=request_timeout,
            operation_timeout=float(operation_timeout),connection=alias, use_m2m=False)
        return target_path

