    def pmtu_discovery(self, **kwargs):
        name = kwargs["name"]
        source_ip = kwargs["source_ip"]
        destination_ip = kwargs["destination_ip"]
        dscp = int(kwargs["dscp"])
        timeout = kwargs.get("timeout", 30)
        alias = kwargs.get("alias", "default")
        operation_id = self.factory.cu_oam.start_pmtu_discovery(name=name, source_ip=source_ip, destination_ip=destination_ip,
                                                                 dscp=dscp, timeout=timeout, connection=alias)

        return self.factory.cu_oam.get_pmtu_discovery_status(operation_id=operation_id, timeout=timeout, connection=alias)

